CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE users(id text PRIMARY KEY,email text UNIQUE NOT NULL,name text NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('superadmin','admin','client')),active boolean NOT NULL DEFAULT true,access_version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles(name text PRIMARY KEY);
INSERT INTO roles VALUES('superadmin'),('admin'),('client');
CREATE TABLE role_permissions(role text REFERENCES roles(name),permission text NOT NULL,PRIMARY KEY(role,permission));
INSERT INTO role_permissions SELECT 'client',unnest(ARRAY['read_brand_report','read_session_evidence','export_brand_report','read_global_host_summary','export_global_host_summary','use_insights']);
INSERT INTO role_permissions SELECT 'admin',unnest(ARRAY['read_brand_report','read_session_evidence','export_brand_report','read_global_host_summary','export_global_host_summary','use_insights','upload_report','review_report','publish_report','manage_host','manage_brand_users','configure_brand_dashboard']);
CREATE TABLE auth_sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),csrf_token text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE access_tokens(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN('invite','reset')),expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE brands(id text PRIMARY KEY,name text NOT NULL,active boolean NOT NULL DEFAULT true,is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE channels(id text PRIMARY KEY,name text UNIQUE NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE studios(id text PRIMARY KEY,name text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE hosts(id text PRIMARY KEY,name text NOT NULL,active boolean NOT NULL DEFAULT true,global_visible boolean NOT NULL DEFAULT true,profile_note text NOT NULL DEFAULT '');
CREATE TABLE user_brand_access(user_id text REFERENCES users(id),brand_id text REFERENCES brands(id),PRIMARY KEY(user_id,brand_id));
CREATE TABLE studio_access(user_id text REFERENCES users(id),studio_id text REFERENCES studios(id),PRIMARY KEY(user_id,studio_id));
CREATE TABLE host_brand_access(host_id text REFERENCES hosts(id),brand_id text REFERENCES brands(id),PRIMARY KEY(host_id,brand_id));
CREATE TABLE brand_channel_accounts(id text PRIMARY KEY,brand_id text NOT NULL REFERENCES brands(id),channel_id text NOT NULL REFERENCES channels(id),name text NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(brand_id,channel_id,name));
CREATE TABLE daily_counters(day date PRIMARY KEY,number integer NOT NULL CHECK(number>0));
CREATE TABLE live_rooms(id text PRIMARY KEY,brand_id text NOT NULL REFERENCES brands(id),account_id text NOT NULL REFERENCES brand_channel_accounts(id),channel_id text NOT NULL REFERENCES channels(id),created_by text NOT NULL REFERENCES users(id),start_at timestamptz,end_at timestamptz,CHECK(end_at>start_at));
CREATE TABLE host_slots(id text PRIMARY KEY,id_line text NOT NULL UNIQUE,room_id text NOT NULL REFERENCES live_rooms(id),brand_id text NOT NULL REFERENCES brands(id),studio_id text NOT NULL REFERENCES studios(id),host_id text NOT NULL REFERENCES hosts(id),start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,business_date date NOT NULL,duration_seconds integer NOT NULL CHECK(duration_seconds>0),notes text NOT NULL DEFAULT '',no_skp text NOT NULL DEFAULT '',pic_h1 text NOT NULL DEFAULT '',created_by text NOT NULL REFERENCES users(id),CHECK(end_at>start_at),EXCLUDE USING gist(room_id WITH =,tstzrange(start_at,end_at,'[)') WITH &&));
CREATE TABLE source_reports(id text PRIMARY KEY,slot_id text NOT NULL REFERENCES host_slots(id),room_id text NOT NULL REFERENCES live_rooms(id),scope text NOT NULL CHECK(scope IN('room','host_slot','snapshot')),period_start timestamptz,period_end timestamptz,captured_at timestamptz,basis text NOT NULL,currency text NOT NULL DEFAULT 'IDR' CHECK(currency='IDR'),definition_version text NOT NULL,period_confirmed boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,created_by text NOT NULL REFERENCES users(id),idempotency_key text UNIQUE NOT NULL,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CHECK(period_end>period_start));
CREATE TABLE attachments(id text PRIMARY KEY,source_report_id text NOT NULL REFERENCES source_reports(id),original_name text NOT NULL,storage_key text UNIQUE NOT NULL,content_type text NOT NULL,content_hash text NOT NULL,bytes bigint NOT NULL CHECK(bytes>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX attachments_hash ON attachments(content_hash);
CREATE TABLE metric_mapping_versions(id text PRIMARY KEY,channel_id text NOT NULL REFERENCES channels(id),label text NOT NULL,confirmed boolean NOT NULL DEFAULT false,is_demo boolean NOT NULL DEFAULT false,created_by text REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE metric_definitions(mapping_version text REFERENCES metric_mapping_versions(id),key text NOT NULL,label text NOT NULL,unit text NOT NULL,kind text NOT NULL CHECK(kind IN('money','count','duration','ratio')),aggregation text NOT NULL,required boolean NOT NULL DEFAULT false,canonical_column integer,canonical_confirmed boolean NOT NULL DEFAULT false,PRIMARY KEY(mapping_version,key));
ALTER TABLE source_reports ADD FOREIGN KEY(definition_version) REFERENCES metric_mapping_versions(id);
CREATE TABLE report_versions(id text PRIMARY KEY,source_report_id text NOT NULL REFERENCES source_reports(id),subject_key text NOT NULL,scope text NOT NULL,basis text NOT NULL,currency text NOT NULL,definition_version text NOT NULL REFERENCES metric_mapping_versions(id),number integer NOT NULL,revision integer NOT NULL DEFAULT 1,status text NOT NULL CHECK(status IN('draft','review','ready','published','archived')),active boolean NOT NULL DEFAULT false,completeness_status text NOT NULL DEFAULT 'incomplete',validity_status text NOT NULL DEFAULT 'unverified',compatibility_status text NOT NULL DEFAULT 'source_only',reason text NOT NULL DEFAULT '',reviewed_by text REFERENCES users(id),reviewed_at timestamptz,published_by text REFERENCES users(id),published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_report_id,number),CHECK(NOT active OR status='published'));
CREATE UNIQUE INDEX report_active_subject ON report_versions(subject_key,scope,basis,currency,definition_version) WHERE active;
CREATE TABLE report_metric_values(version_id text REFERENCES report_versions(id),metric_key text NOT NULL,value numeric(24,4) CHECK(value>=0),raw_label text NOT NULL DEFAULT '',raw_value text NOT NULL DEFAULT '',unit text NOT NULL,evidence_text text NOT NULL DEFAULT '',attachment_id text REFERENCES attachments(id),page_number integer CHECK(page_number>0),bounding_box jsonb,rounded_display boolean NOT NULL DEFAULT false,definition_status text NOT NULL DEFAULT 'source',validation_flags jsonb NOT NULL DEFAULT '[]',PRIMARY KEY(version_id,metric_key));
CREATE TABLE processing_jobs(id text PRIMARY KEY,source_report_id text NOT NULL REFERENCES source_reports(id),input_revision integer NOT NULL,mode text NOT NULL,scenario text NOT NULL DEFAULT '',status text NOT NULL CHECK(status IN('queued','running','succeeded','failed','review')),idempotency_key text UNIQUE NOT NULL,attempts integer NOT NULL DEFAULT 0,lease_token text,lease_until timestamptz,worker_id text,next_run_at timestamptz NOT NULL DEFAULT now(),last_error text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX job_one_active ON processing_jobs(source_report_id,input_revision) WHERE status IN('queued','running');
CREATE INDEX jobs_claim ON processing_jobs(status,next_run_at,lease_until);
CREATE TABLE extraction_runs(id text PRIMARY KEY,job_id text NOT NULL REFERENCES processing_jobs(id),attempt integer NOT NULL,prompt_version text NOT NULL DEFAULT 'v1',mapping_version text NOT NULL,provider text,model text,usage jsonb,result jsonb,error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,attempt));
CREATE TABLE extracted_values(id bigserial PRIMARY KEY,run_id text NOT NULL REFERENCES extraction_runs(id),attachment_id text REFERENCES attachments(id),page_number integer,evidence_text text NOT NULL,raw_label text NOT NULL,raw_value text,normalized_value numeric(24,4),unit text NOT NULL,confidence numeric,bounding_box jsonb,precision text NOT NULL DEFAULT 'source',mapping_version text NOT NULL,definition_status text NOT NULL,validation_flags jsonb NOT NULL DEFAULT '[]');
CREATE TABLE dashboard_configs(brand_id text PRIMARY KEY REFERENCES brands(id),widgets jsonb NOT NULL DEFAULT '["views","interactions","activity","sales","sessions"]',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE export_logs(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),scope text NOT NULL,filters jsonb NOT NULL,versions jsonb NOT NULL,format text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE insights(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),brand_id text REFERENCES brands(id),filters jsonb NOT NULL,source_revision text NOT NULL,body text NOT NULL,stale boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,user_id text REFERENCES users(id),action text NOT NULL,object_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',request_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app_settings(key text PRIMARY KEY,value jsonb NOT NULL);
INSERT INTO app_settings VALUES('sample_threshold','3');
CREATE INDEX slots_filter ON host_slots(brand_id,business_date,host_id,studio_id);
CREATE INDEX report_final ON report_versions(source_report_id,active,status);
CREATE INDEX auth_expiry ON auth_sessions(expires_at);
